export default function PfmCategoryIcon({ category, size = 32, className = "" }: PfmCategoryIconProps) {
  const definition = getPfmCategory(category);
  const paths = PFM_CATEGORY_ICONS[definition.name];
  const viewBox = PFM_ICON_VIEW_BOXES[definition.name] ?? DEFAULT_ICON_VIEW_BOX;

  if (paths) {
    return (
      <span
        className={`inline-flex shrink-0 items-center justify-center ${className}`}
        style={{
          width: `${size}px`,
          height: `${size}px`,
          aspectRatio: "1 / 1",
        }}
        aria-label={`${definition.name} PFM category`}
        data-pfm-category={definition.name}
        data-pfm-icon-source={PFM_ICON_SOURCE}
        data-pfm-icon-rendering="svg"
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width={ICON_GLYPH_SIZE}
          height={ICON_GLYPH_SIZE}
          viewBox={viewBox}
          fill="none"
          style={{
            width: `${ICON_GLYPH_SIZE}px`,
            height: `${ICON_GLYPH_SIZE}px`,
            aspectRatio: "1 / 1",
          }}
          aria-hidden="true"
        >
          {paths.map((path, index) => (
            <path
              key={`${definition.name}-${index}`}
              d={path.d}
              fill={`var(${definition.colorVar})`}
              fillRule={path.fillRule}
              clipRule={path.clipRule}
            />
          ))}
        </svg>
      </span>
    );
  }

  const iconSize = Math.max(18, Math.round(size * 0.56));

  return (
    <span
      className={`inline-flex shrink-0 items-center justify-center rounded-full font-['UniCredit',sans-serif] font-bold leading-none text-[var(--uc-static-white)] ${className}`}
      style={{
        width: `${size}px`,
        height: `${size}px`,
        backgroundColor: `var(${definition.colorVar})`,
        fontSize: `${iconSize}px`,
      }}
      aria-label={`${definition.name} PFM category`}
      data-pfm-category={definition.name}
      data-pfm-icon-source={PFM_ICON_SOURCE}
    >
      {definition.fallbackInitial}
    </span>
  );
}
